$ErrorActionPreference='Stop'; $ProgressPreference='SilentlyContinue'
try {
if((Get-ADDomain).DNSRoot -ne 'q1lab.test'){throw 'Wrong independent forest'}
New-Item 'C:\Q1Evidence\updates' -ItemType Directory -Force | Out-Null
$task='GoadQ1-Update-KB5062557'
if(Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue){throw 'Owned update task already exists'}
[IO.File]::WriteAllBytes('C:\Windows\Temp\Q1Install_KB5062557.ps1',[Convert]::FromBase64String(''))
if((Get-FileHash 'C:\Windows\Temp\Q1Install_KB5062557.ps1' -Algorithm SHA256).Hash.ToLower() -ne 'd23726ee1ce0aa707266cb7f658a57c889daa4c0c07abc914e496a1373909ff6'){throw 'Task source differs'}
$action=New-ScheduledTaskAction -Execute powershell.exe -Argument '-NoProfile -File C:\Windows\Temp\Q1Install_KB5062557.ps1'
$principal=New-ScheduledTaskPrincipal -UserId SYSTEM -LogonType ServiceAccount -RunLevel Highest
$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Hours 2)
Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings | Out-Null
Start-ScheduledTask -TaskName $task
'OWNED_LOCAL_UPDATE_TASK_STARTED'

'__Q1_PHASE_COMPLETE__'
} catch { '__Q1_PHASE_FAILURE__'; $_.Exception.ToString(); exit 1 }